const item = $input.first();
const politica = item.json;
if (!Array.isArray(politica.regras) || !Array.isArray(politica.regrasGerais) || !Array.isArray(politica.categorias)) {
  throw new Error('Relatório anterior não contém o contrato de regras esperado.');
}
if (!item.binary?.data || !item.binary?.relatorio) throw new Error('Arquivos originais do relatório não estão presentes.');

// Esta etapa lê as regras consolidadas e cria apenas uma camada de consulta.
// Nenhuma regra, efeito, condição, limite, exceção ou evidência é modificado.
const regras = [...politica.regras, ...politica.regrasGerais];
const porId = new Map(regras.map(r => [r.id, r]));
if (porId.size !== regras.length) throw new Error('IDs repetidos impedem agrupar regras com segurança.');
const limpa = v => String(v ?? '').replace(/\s+/g, ' ').trim();
const grupos = [];
const oportunidades = [];

for (const categoria of politica.categorias) {
  const locais = politica.regras.filter(r => r.categoria === categoria.id);
  if (!locais.length) continue;
  const docs = new Map(), aprovacoes = new Map();
  const relacionadas = new Set();
  for (const r of locais) {
    for (const id of [...(r.regrasRelacionadas ?? []), ...(r.regrasGeraisAplicaveis ?? [])]) {
      if (porId.has(id)) relacionadas.add(id);
    }
    for (const ex of r.excecoes ?? []) for (const id of ex.regrasModificadas ?? []) if (porId.has(id)) relacionadas.add(id);
    for (const d of r.documentosExigidos ?? []) {
      const chave = limpa(d).toLowerCase();
      if (!chave) continue;
      if (!docs.has(chave)) docs.set(chave, { documento: d, regras: [] });
      docs.get(chave).regras.push(r.id);
    }
    for (const a of r.aprovacoesExigidas ?? []) {
      const chave = limpa(a.quem).toLowerCase() + '|' + limpa(a.momento).toLowerCase();
      if (!limpa(a.quem)) continue;
      if (!aprovacoes.has(chave)) aprovacoes.set(chave, { quem: a.quem, momento: a.momento ?? null, regras: [] });
      aprovacoes.get(chave).regras.push(r.id);
    }
  }
  const compartilhados = [...docs.values()].filter(x => new Set(x.regras).size > 1);
  const aprovadoresCompartilhados = [...aprovacoes.values()].filter(x => new Set(x.regras).size > 1);
  const manual = locais.filter(r => r.prontidao !== 'estruturada').map(r => r.id);
  grupos.push({
    categoriaId: categoria.id,
    categoria: categoria.nome,
    regras: locais.map(r => r.id),
    regrasRelacionadas: [...relacionadas].sort(),
    efeitosPresentes: [...new Set(locais.map(r => r.efeito))].sort(),
    verificacoesDocumentaisCompartilhadas: compartilhados,
    aprovadoresCompartilhados,
    regrasQueExigemCuidado: manual,
    observacao: 'Agrupamento para leitura e coleta de dados. Cada regra continua aplicável apenas no próprio escopo e com suas condições.'
  });
  for (const d of compartilhados) oportunidades.push({
    tipo: 'coleta_documental', categoria: categoria.nome, regras: [...new Set(d.regras)],
    sugestao: 'Avaliar uma coleta única do documento "' + d.documento + '" no formulário, mantendo a checagem individual de cada regra.',
    condicao: 'Só reutilizar a evidência quando titular, data, escopo e validade exigidos por cada regra forem compatíveis.'
  });
  for (const a of aprovadoresCompartilhados) oportunidades.push({
    tipo: 'registro_aprovacao', categoria: categoria.nome, regras: [...new Set(a.regras)],
    sugestao: 'Avaliar um registro comum da aprovação de ' + a.quem + ', sem dispensar a autorização exigida para cada situação.',
    condicao: 'Confirmar que objeto, momento e autoridade da aprovação são os mesmos em todas as regras relacionadas.'
  });
  if (manual.length) oportunidades.push({
    tipo: 'roteamento_para_revisao', categoria: categoria.nome, regras: manual,
    sugestao: 'Apresentar essas regras juntas ao revisor com as pendências e evidências de cada uma.',
    condicao: 'Não converter revisão manual ou parâmetro ausente em autorização automática.'
  });
}

const camadaContextual = {
  natureza: 'visao_orientativa',
  versao: 1,
  politicaIntacta: true,
  regraDeSeguranca: 'Nenhuma sugestão altera ou substitui regras, limites, proibições, aprovações, exceções ou evidências da política.',
  totalRegrasFonte: regras.length,
  grupos,
  oportunidades,
  pendenciasMantidas: (politica.pendencias ?? []).length,
  questoesMantidas: (politica.questoesInterpretacao ?? []).length
};
const resultado = { ...politica, camadaContextual };

const textoOriginal = (await this.helpers.getBinaryDataBuffer(0, 'relatorio')).toString('utf8');
const marcador = 'QUADRO FINAL — CONTAGEM DE REGRAS ÚNICAS';
const posicao = textoOriginal.lastIndexOf(marcador);
if (posicao < 0) throw new Error('Quadro final não encontrado; o relatório original foi preservado.');
const secao = ['CAMADA CONTEXTUAL — SUGESTÕES PARA REVISÃO',
  'Esta camada organiza a leitura e propõe reaproveitamento de verificações. As regras originais permanecem intactas.',
  `Grupos de contexto: ${grupos.length} | Sugestões: ${oportunidades.length} | Regras analisadas: ${regras.length}`, ''];
for (const grupo of grupos) {
  secao.push(grupo.categoria + ' — regras: ' + grupo.regras.join(', '));
  if (grupo.regrasRelacionadas.length) secao.push('Relacionadas: ' + grupo.regrasRelacionadas.join(', '));
  if (grupo.regrasQueExigemCuidado.length) secao.push('Revisão/parâmetro: ' + grupo.regrasQueExigemCuidado.join(', '));
  for (const op of oportunidades.filter(x => x.categoria === grupo.categoria)) {
    secao.push('• ' + op.sugestao + ' [regras: ' + op.regras.join(', ') + ']');
    secao.push('  Condição: ' + op.condicao);
  }
  secao.push('');
}
const textoNovo = textoOriginal.slice(0, posicao).trimEnd() + '\n\n' + secao.join('\n').trimEnd() + '\n\n' + textoOriginal.slice(posicao);
const jsonNome = item.binary.data.fileName ?? 'politica.json';
const txtNome = item.binary.relatorio.fileName ?? 'relatorio.txt';
return [{ json: resultado, binary: {
  ...item.binary,
  data: await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(resultado, null, 2), 'utf8'), jsonNome, 'application/json'),
  relatorio: await this.helpers.prepareBinaryData(Buffer.from(textoNovo, 'utf8'), txtNome, 'text/plain')
} }];
